struct PluginMessageBuilder {
  typedef PluginMessage Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_id(uint64_t id) {
    fbb_.AddElement<uint64_t>(PluginMessage::VT_ID, id, 0);
  }
  void add_source_plugin(uint32_t source_plugin) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_SOURCE_PLUGIN, source_plugin, 0);
  }
  void add_target_plugin(uint32_t target_plugin) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_TARGET_PLUGIN, target_plugin, 0);
  }
  void add_target_type(orbpro::plugin::PluginType target_type) {
    fbb_.AddElement<uint8_t>(PluginMessage::VT_TARGET_TYPE, static_cast<uint8_t>(target_type), 0);
  }
  void add_timestamp(double timestamp) {
    fbb_.AddElement<double>(PluginMessage::VT_TIMESTAMP, timestamp, 0.0);
  }
  void add_request_type(orbpro::plugin::RequestPayload request_type) {
    fbb_.AddElement<uint8_t>(PluginMessage::VT_REQUEST_TYPE, static_cast<uint8_t>(request_type), 0);
  }
  void add_request(::flatbuffers::Offset<void> request) {
    fbb_.AddOffset(PluginMessage::VT_REQUEST, request);
  }
  void add_response_type(orbpro::plugin::ResponsePayload response_type) {
    fbb_.AddElement<uint8_t>(PluginMessage::VT_RESPONSE_TYPE, static_cast<uint8_t>(response_type), 0);
  }
  void add_response(::flatbuffers::Offset<void> response) {
    fbb_.AddOffset(PluginMessage::VT_RESPONSE, response);
  }
  void add_arena_input_offset(uint32_t arena_input_offset) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_ARENA_INPUT_OFFSET, arena_input_offset, 0);
  }
  void add_arena_input_size(uint32_t arena_input_size) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_ARENA_INPUT_SIZE, arena_input_size, 0);
  }
  void add_arena_output_offset(uint32_t arena_output_offset) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_ARENA_OUTPUT_OFFSET, arena_output_offset, 0);
  }
  void add_arena_output_size(uint32_t arena_output_size) {
    fbb_.AddElement<uint32_t>(PluginMessage::VT_ARENA_OUTPUT_SIZE, arena_output_size, 0);
  }
  explicit PluginMessageBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<PluginMessage> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<PluginMessage>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<PluginMessage> CreatePluginMessage(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint64_t id = 0,
    uint32_t source_plugin = 0,
    uint32_t target_plugin = 0,
    orbpro::plugin::PluginType target_type = orbpro::plugin::PluginType_SENSOR,
    double timestamp = 0.0,
    orbpro::plugin::RequestPayload request_type = orbpro::plugin::RequestPayload_NONE,
    ::flatbuffers::Offset<void> request = 0,
    orbpro::plugin::ResponsePayload response_type = orbpro::plugin::ResponsePayload_NONE,
    ::flatbuffers::Offset<void> response = 0,
    uint32_t arena_input_offset = 0,
    uint32_t arena_input_size = 0,
    uint32_t arena_output_offset = 0,
    uint32_t arena_output_size = 0) {
  PluginMessageBuilder builder_(_fbb);
  builder_.add_timestamp(timestamp);
  builder_.add_id(id);
  builder_.add_arena_output_size(arena_output_size);
  builder_.add_arena_output_offset(arena_output_offset);
  builder_.add_arena_input_size(arena_input_size);
  builder_.add_arena_input_offset(arena_input_offset);
  builder_.add_response(response);
  builder_.add_request(request);
  builder_.add_target_plugin(target_plugin);
  builder_.add_source_plugin(source_plugin);
  builder_.add_response_type(response_type);
  builder_.add_request_type(request_type);
  builder_.add_target_type(target_type);
  return builder_.Finish();
}

template <bool B>
inline bool VerifyRequestPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, RequestPayload type) {
  switch (type) {
    case RequestPayload_NONE: {
      return true;
    }
    case RequestPayload_StreamInvoke: {
      auto ptr = reinterpret_cast<const orbpro::plugin::StreamInvokeRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_PropagatorInit: {
      auto ptr = reinterpret_cast<const orbpro::propagator::PropagatorInit *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_PropagatorBatch: {
      auto ptr = reinterpret_cast<const orbpro::propagator::PropagatorBatchRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_SensorConfig: {
      auto ptr = reinterpret_cast<const orbpro::sensor::SensorConfig *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_SensorBatch: {
      auto ptr = reinterpret_cast<const orbpro::sensor::SensorBatchRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_SDFConfig: {
      auto ptr = reinterpret_cast<const orbpro::sdf::SDFConfig *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_SDFBatch: {
      auto ptr = reinterpret_cast<const orbpro::sdf::SDFBatchRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_ShaderCompile: {
      auto ptr = reinterpret_cast<const orbpro::plugin::ShaderCompileRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case RequestPayload_RawData: {
      auto ptr = reinterpret_cast<const orbpro::plugin::RawDataPayload *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyRequestPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyRequestPayload(
        verifier,  values->Get(i), types->GetEnum<RequestPayload>(i))) {
      return false;
    }
  }
  return true;
}

template <bool B>
inline bool VerifyResponsePayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, ResponsePayload type) {
  switch (type) {
    case ResponsePayload_NONE: {
      return true;
    }
    case ResponsePayload_StreamInvoke: {
      auto ptr = reinterpret_cast<const orbpro::plugin::StreamInvokeResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_PropagatorBatch: {
      auto ptr = reinterpret_cast<const orbpro::propagator::PropagatorBatchResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_SensorBatch: {
      auto ptr = reinterpret_cast<const orbpro::sensor::SensorBatchResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_SDFBatch: {
      auto ptr = reinterpret_cast<const orbpro::sdf::SDFBatchResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_ShaderCompile: {
      auto ptr = reinterpret_cast<const orbpro::plugin::ShaderCompileResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_Error: {
      auto ptr = reinterpret_cast<const orbpro::plugin::ErrorResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ResponsePayload_RawData: {
      auto ptr = reinterpret_cast<const orbpro::plugin::RawDataPayload *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyResponsePayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyResponsePayload(
        verifier,  values->Get(i), types->GetEnum<ResponsePayload>(i))) {
      return false;
    }
  }
  return true;
}

